import os
exec(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'lesson_video.py'), encoding='utf-8').read())
AR = str.maketrans('0123456789', '٠١٢٣٤٥٦٧٨٩')
def ar(n): return str(n).translate(AR)
def P(b, x=None): return f'<span class="b">{ar(b)}' + (f'<sup>{ar(x)}</sup>' if x else '') + '</span>'
def K(t): return f'<b style="color: #C2410C">{t}</b>'
def TREE(t, h=300):   # شجرة عوامل: الأعداد الأولية في النهايات داخل دوائر
    U, V, items, leaves = 110, 120, [], [0]
    def lay(n, d):
        if isinstance(n, tuple):
            xl, xr = lay(n[1], d + 1), lay(n[2], d + 1); x = (xl + xr) / 2
            items.append(('n', n[0], x, d)); items.append(('l', x, d, xl)); items.append(('l', x, d, xr)); return x
        x = leaves[0] * U + U / 2; leaves[0] += 1; items.append(('p', n, x, d)); return x
    lay(t, 0)
    D = max(i[3] for i in items if i[0] != 'l') + 1
    out = [f'<line x1="{x}" y1="{d * V + 78}" x2="{xc}" y2="{(d + 1) * V + 20}" stroke="#4A5E80" stroke-width="5" stroke-linecap="round"/>' for k, x, d, xc in items if k == 'l']
    for k, n, x, d in (i for i in items if i[0] != 'l'):
        y = d * V + 60
        c = f'<circle cx="{x}" cy="{y - 4}" r="40" fill="#FFE08A" stroke="#C7361B" stroke-width="5"/>' if k == 'p' else ''
        out.append(c + f'<text x="{x}" y="{y + 14}" text-anchor="middle" font-size="52" font-weight="900" fill="#14305C" font-family="Cairo">{ar(n)}</text>')
    return f'<svg viewBox="0 0 {leaves[0] * U} {D * V}" style="height: {h}px; width: auto; vertical-align: middle">{"".join(out)}</svg>'
